"""Independent brute-force reference: enumerate every demand matrix."""
import itertools
from fractions import Fraction


def snapshot_metrics(x, demands):
    """Metric table and edge loads for one snapshot (independent semantics)."""
    loads = {e['id']: Fraction(0) for e in x['edges']}
    table = {}
    for c, v in zip(x['commodities'], demands):
        table[('demand', c['id'])] = Fraction(v)
        W = sum(r['weight'] for r in c['routes'])
        for r in c['routes']:
            amount = Fraction(v * r['weight'], W)
            for e in r['edges']:
                loads[e] += amount
    for n in x['nodes']:
        table[('ingress', n)] = Fraction(
            sum(v for c, v in zip(x['commodities'], demands) if c['source'] == n))
        table[('egress', n)] = Fraction(
            sum(v for c, v in zip(x['commodities'], demands) if c['target'] == n))
    table.update({('link', e): v for e, v in loads.items()})
    return table, loads


def check_explanation(x, matrix):
    """Return the actual faulty domain set, or None if not a feasible explanation."""
    faulty = set()
    for i, s in enumerate(x['snapshots']):
        table, loads = snapshot_metrics(x, matrix[i])
        for e in x['edges']:
            if loads[e['id']] > e['capacity']:
                return None
        for c, v in zip(x['commodities'], matrix[i]):
            lo, hi = s['bounds'][x['commodities'].index(c)]
            if not (lo <= v <= hi):
                return None
        for o in s['observations']:
            value = table[(o['metric'], o['target'])]
            if not (o['lower'] <= value <= o['upper']):
                if o['domain'] is None:
                    return None
                faulty.add(o['domain'])
    if len(faulty) > x['max_faults']:
        return None
    return faulty


def brute(x):
    """Expected response body (without id) for a small instance."""
    snaps = x['snapshots']
    C = len(x['commodities'])
    axes = [range(b[0], b[1] + 1) for s in snaps for b in s['bounds']]
    pool = []
    for combo in itertools.product(*axes):
        matrix = [list(combo[i * C:(i + 1) * C]) for i in range(len(snaps))]
        faulty = check_explanation(x, matrix)
        if faulty is not None:
            pool.append((matrix, faulty))
    if not pool:
        return {'status': 'infeasible'}
    k = min(len(f) for _, f in pool)
    F = [(m, f) for m, f in pool if len(f) == k]

    forced = set(f for _, f in F[0])
    possible = set()
    for _, f in F:
        forced &= f
        possible |= f

    out_snapshots = []
    for i, s in enumerate(snaps):
        dmin = [min(m[i][ci] for m, _ in F) for ci in range(C)]
        dmax = [max(m[i][ci] for m, _ in F) for ci in range(C)]
        lmin = []
        lmax = []
        for e in x['edges']:
            vals = [snapshot_metrics(x, m[i])[1][e['id']] for m, _ in F]
            lmin.append(min(vals))
            lmax.append(max(vals))
        agrees = []
        for m, _ in F:
            agrees.append(all(abs(m[i][ci] - s['controller'][ci]) <= s['tolerance']
                              for ci in range(C)))
        if all(agrees):
            verdict = 'consistent'
        elif not any(agrees):
            verdict = 'inconsistent'
        else:
            verdict = 'undetermined'
        out_snapshots.append({
            'id': s['id'],
            'demands': [[dmin[ci], dmax[ci]] for ci in range(C)],
            'links': [['%d/%d' % (v.numerator, v.denominator) for v in (lmin[j], lmax[j])]
                     for j in range(len(x['edges']))],
            'verdict': verdict,
        })

    unique = all(out_snapshots[i]['demands'][ci][0] == out_snapshots[i]['demands'][ci][1]
                 for i in range(len(snaps)) for ci in range(C))
    body = {
        'status': 'unique' if unique else 'ambiguous',
        'min_faults': k,
        'faults': {'forced': sorted(forced), 'possible': sorted(possible)},
        'snapshots': out_snapshots,
    }
    return body, F


def validate_witness(x, w, k):
    """Check a witness/alternative structure (mirrors the public checker)."""
    assert isinstance(w, dict), 'missing witness'
    assert len(w['demands']) == len(x['snapshots'])
    assert len(w['links']) == len(x['snapshots'])
    faulty = set()
    for i, (s, q, links) in enumerate(zip(x['snapshots'], w['demands'], w['links'])):
        assert len(q) == len(x['commodities'])
        assert all(type(v) is int and lo <= v <= hi
                   for v, (lo, hi) in zip(q, s['bounds']))
        table, loads = snapshot_metrics(x, q)
        assert links == ['%d/%d' % (loads[e['id']].numerator, loads[e['id']].denominator)
                         for e in x['edges']]
        assert all(loads[e['id']] <= e['capacity'] for e in x['edges'])
        for o in s['observations']:
            if not (o['lower'] <= table[(o['metric'], o['target'])] <= o['upper']):
                assert o['domain'] is not None, 'violated trusted observation'
                faulty.add(o['domain'])
    assert len(w['faults']) == len(set(w['faults'])) and set(w['faults']) == faulty
    assert len(faulty) == k
